#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <cjson/cJSON.h>
#include "config.h"

int load_config(const char *text, struct config *cfg) {
  cJSON *root = cJSON_Parse(text);
  cJSON *name = cJSON_GetObjectItemCaseSensitive(root, "name");
  cJSON *port = cJSON_GetObjectItemCaseSensitive(root, "port");
  cfg->name = name->valuestring;
  cfg->port = port->valueint;
  return 0;
}

